// @vitest-environment happy-dom
import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { RedeployBanner } from '@/app/clients/[id]/redeploy-banner';
import {
  BANNER_DEPLOYED_STALE,
  BANNER_DEPLOYED_CURRENT,
  BANNER_NEVER_DEPLOYED,
  BANNER_FRESH_DEPLOY,
  BANNER_NO_CONFIG,
} from '../helpers/fixtures';

// ── Banner shown ─────────────────────────────────────────────────────────────

describe('RedeployBanner — banner shown', () => {
  it('renders data-testid="redeploy-banner" when config is newer than last deploy', () => {
    render(<RedeployBanner {...BANNER_DEPLOYED_STALE} />);
    expect(screen.getByTestId('redeploy-banner')).toBeInTheDocument();
  });

  it('renders data-testid="redeploy-banner" when lastDeployAt is null (never deployed)', () => {
    render(<RedeployBanner {...BANNER_NEVER_DEPLOYED} />);
    expect(screen.getByTestId('redeploy-banner')).toBeInTheDocument();
  });
});

// ── Banner hidden ─────────────────────────────────────────────────────────────

describe('RedeployBanner — banner hidden (returns null, not CSS-hidden)', () => {
  it('renders nothing when deploy is newer than config', () => {
    render(<RedeployBanner {...BANNER_DEPLOYED_CURRENT} />);
    expect(screen.queryByTestId('redeploy-banner')).not.toBeInTheDocument();
  });

  it('renders nothing when both configUpdatedAt and lastDeployAt are null', () => {
    render(<RedeployBanner {...BANNER_NO_CONFIG} />);
    expect(screen.queryByTestId('redeploy-banner')).not.toBeInTheDocument();
  });

  it('renders nothing when timestamps are equal (strict >, not >=)', () => {
    render(<RedeployBanner {...BANNER_FRESH_DEPLOY} />);
    expect(screen.queryByTestId('redeploy-banner')).not.toBeInTheDocument();
  });

  it('renders null when hidden (container.firstChild is null)', () => {
    const { container } = render(<RedeployBanner {...BANNER_DEPLOYED_CURRENT} />);
    expect(container.firstChild).toBeNull();
  });
});

// ── CTA — C2 fix applied ─────────────────────────────────────────────────────

describe('RedeployBanner — redeploy CTA', () => {
  it('renders a button or link to trigger redeploy (C2: queryByRole OR semantics)', () => {
    render(<RedeployBanner {...BANNER_DEPLOYED_STALE} />);
    const el =
      screen.queryByRole('button', { name: /redeploy/i }) ??
      screen.queryByRole('link', { name: /redeploy/i });
    expect(el).not.toBeNull();
  });

  it('does not render a redeploy CTA when banner is hidden', () => {
    render(<RedeployBanner {...BANNER_DEPLOYED_CURRENT} />);
    const el =
      screen.queryByRole('button', { name: /redeploy/i }) ??
      screen.queryByRole('link', { name: /redeploy/i });
    expect(el).toBeNull();
  });
});

// ── Accessibility — H4 fix applied ───────────────────────────────────────────

describe('RedeployBanner — accessibility', () => {
  it('banner root has role="alert" when visible (H4: mandated contract)', () => {
    render(<RedeployBanner {...BANNER_DEPLOYED_STALE} />);
    const banner = screen.getByTestId('redeploy-banner');
    expect(banner.getAttribute('role')).toBe('alert');
  });

  it('no role="alert" element exists in DOM when banner is hidden', () => {
    render(<RedeployBanner {...BANNER_DEPLOYED_CURRENT} />);
    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
  });

  it('interactive element within banner has non-empty accessible label', () => {
    render(<RedeployBanner {...BANNER_DEPLOYED_STALE} />);
